licitante\": \"texto objetivo\",\n  \"confianca\": 0.0,\n  \"probabilidades\": {\n    \"OBRA\": 0.0,\n    \"DEMO\": 0.0,\n    \"SOB_DEMANDA\": 0.0,\n    \"TRIAGEM_MANUAL\": 0.0\n  }\n}\n\nCHAMADO:\n{{ JSON.stringify($json) }}";
